GimCorpus.put(407,0,[[1,2,"ואיסור החמץ וכו'. כתב הראב\"ד ז\"ל דוקא לשיעוריהן אבל לענין ביעור ולענין אכילה יש הפרש ביניהם שהחמץ אם נפסל מאכילת הכלב אין זקוק לבער והשאור אף על פי שהוא נפסל חייב לבער לפי שהוא ראוי לשחקו ולחמץ בו כמה עיסות אלא א\"כ יחדו לישיבה וטח פניו בטיט. ומה ששנו בתוספתא הפת שעיפשה חייב לבער מפני שהוא ראוי לשחקה וכו' בפת של שאור קאמר דאי בחמץ לא היה צריך לזה הטעם עכ\"ל:",1,0],[1,6,"כגון כותח הבבלי וכו'. כתב הראב\"ד ז\"ל א\"א הרב פסק באלו כרבנן משום דאין בהן כזית בכדי אכילת פרס:",1,0],[1,8,"וכל האוכל בזמן הזה לוקה מן התורה. א\"א מלקות מחצות ואילך אינו מחוור דכיון דקי\"ל כרבי שמעון בלפני זמנו ואחר זמנו דלא דריש הנך קראי לא תאכל לא תאכלו בלפני זמנו ואחר זמנו נהי דאסור באכילה מן התורה מביום הראשון תשביתו שאור או מלא תשחט על חמץ כדרבה אבל איסור הנאה ליכא מן התורה ומלקות נמי ליתא:",1,0],[2,6,"חורי הבית התחתונים וכו'. כתב הראב\"ד ז\"ל טעה בשמן שאף על פי שמסתפק אינו צריך לפי שיש קבע לסיפוקו עכ\"ל:",1,0],[2,10,"הניח תשעה וכו'. כתב הראב\"ד ז\"ל לא מיחוורא הא מילתא אלא לענין בטול אבל לענין בדיקה ספיקא דרבנן הוא עכ\"ל:",1,0],[2,11,"שני צבורין וכו' עד שאין כאן קבוע. כתב הראב\"ד ז\"ל זה שבוש דקבוע ודאי הוא אלא שתולין לקולא דהוה ליה כספק ביאה לענין בדיקה ותולין זה בזה ויש לומר אף לענין ביטול דומיא דטומאה. ויש אומרים דלא אמרו תולין זה בזה לטומאה אלא לאוכלי טהרות וכן לענין בדיקה אבל לביטול אזלינן לחומרא ויש דברים דאפילו בדאורייתא אזלינן לקולא כגון בדק ולא מצא כרבנן דפליגי על ר\"מ אי נמי בבדק ומצא כרשב\"ג דפליג אדרבי וכן הניח בזוית זו ומצא בזוית אחרת כרשב\"ג לקולא דפליג על רבי עכ\"ל:",1,0],[2,12,"הניח חמץ בזוית זו. א\"א הרבה שבושים יש בזו הפיסקא הניח בזוית זו וכו' ואינו צריך לבדוק כרשב\"ג דפליג אדרבי הניח תשע ומצא עשר צריך לבדוק כרבנן. תשעה ציבורין של חמץ ודאי צריך בדיקה בא עכבר ונטל חמץ ספק נכנס לבית זה או לא נכנס אינו צריך בדיקה עכ\"ל:",1,0],[2,14,"היה חמץ בבור. כתב הראב\"ד ז\"ל לפי שיטתו שכתב כאת\"ל השנוים בגמ' אף זה צריך סולם להעלותו [ומ\"מ טעות גדולה אני רואה בדבריו שאמר א\"צ סולם להעלותו] אלא מבטלו בלבו ודיו נדמה בעיניו דרבא לכתחלה קא מבעיא ליה וטעות גדולה היא זו דהיינו מטמין בבורות אלא כשבדק וביטל ולאחר איסורו מצא וזו היא שאלתו עכ\"ל:",1,0],[3,3,"חל י\"ד להיות בשבת. כתב הראב\"ד ז\"ל הרב לא כתב כן אלא בתרומה הוא שמבער ומשייר אבל בחולין אינו מבער כלום אלא בזמנו כר\"א בן יהודה איש ברתותא וכר\"א בן צדוק דתרווייהו ס\"ל כהדדי וכן עיקר עכ\"ל:",1,0],[3,8,"לפיכך אם לא ביטל וכו'. כתב הראב\"ד ז\"ל אולי סובר זה המחבר משש שעות ולמעלה בלא יראה ולא ימצא ואינו כן דשבעת ימים כתיב עכ\"ל:",1,0],[4,4,"עכו\"ם אנס שהפקיד וכו'. כתב הראב\"ד ז\"ל דבר זה הוציא ממאי דאמר להו רבא לבני מחוזא בעירו חמירא דבני חילא כיון דאילו מיגניב או מיתביד ברשותייכו קאי ובעיתו לשלומי כדידכו דמי ונדמה ליה שזה האחריות מן האונס הוא ועל כרחם היה וא\"כ במוצאי הפסח היכן היה נמצא שהיה אומר להם רב נחמן פוקו ואייתו לן חמירא דבני חילא והלא נשרף היה כשלהם אלא ודאי לא היה אונס בדבר כלל ויכולים היו להחזירו לשמירת עצמן כשירצו וע\"כ החזירוהו להם ומוצאי הפסח נטלוהו מהם והתשלומין שהם מן האונס אינן כדין האחריות, עכ\"ל:",1,0],[4,5,"ישראל שהרהין וכו'. כתב הראב\"ד לא נהיר ולא צהיר אלא אפילו לא הגיע זמנו עד לאחר הפסח אינו עובר עליו ואם הגיע זמנו קודם הפסח אפי' לא אמר מעכשיו קנאו שאין דין אסמכתא לעכו\"ם ע\"כ: ל",1,0],[4,10,"וכן הקילור וכו'. כתב הראב\"ד ז\"ל זה שבוש דמאחר קבל ומטעם אחר ולא מטעמו:",1,0],[4,11,"הפת עצמה וכו'. כתב הראב\"ד ז\"ל בירושלמי מפרש בשנסרחה ולבסוף נתחמצה עכ\"ל:",1,0],[4,11,"בגדים שכבסו וכו'. כתב הראב\"ד ז\"ל אין זה טעם אלא שכבר נפסל מן אכילת הכלב ועל כל זה שהוא כמו שייחדוהו לישיבה וטח פניו בטיט עכ\"ל:",2,0],[5,2,"אין (אסור) [באין] וכו'. כתב הראב\"ד ז\"ל אין דבר זה פשוט ולא הכל מודים בו דנהי דאין עושין חמץ גמור ואין חייבים על חמוצו כרת אבל נוקשה מיהת הוי ואסור עכ\"ל:",1,0],[5,13,"כל זמן שאדם עוסק וכו'. כתב הראב\"ד ז\"ל אנו אין בידינו אלא כל זמן שהעיסה מצה קולה צלול כשאדם מקיש עליה אבל כשהיא מחמצת אע\"פ שאין בה סדקין ולא הכסיפו פניה קולה משתקע כחרש והחרשות גם הוא סימן לחימוץ ואם הגביה ידו ממנו אסורה והוא שיהא שם אחרת שהחמיצה שנסדקה או שהכסיפו פניה ואם אין שם אחרת ושהתה כדי מיל נמי אסורה עכ\"ל:",1,0],[5,20,"מותר ליתן התבלין וכו'. כתב הראב\"ד ז\"ל זהו ע\"ד הרב ז\"ל שסומך על דברי ר\"ע שאמר לשתי לר' אליעזר ור' יהושע עיסה ביין שמן ודבש ולא אמרו לי דבר ועל דברי ריב\"ל שאמר מיומא קמא לושו לי בחלבא. ואני אומר אולי לא נאמר אלא בזריזים שהיו אופין אותו מיד אבל להתיר לכל אדם כשאר עיסות לא וכן עיקר עכ\"ל:",1,0],[6,2,"בלע מצה וכו'. כתב הראב\"ד ז\"ל זה שבוש שאין זה טעם למרור אלא שאינו טועם טעם מרור אא\"כ לעסו עכ\"ל:",1,0],[6,5,"העושה עיסה מן ההטים וכו'. כתב הראב\"ד ז\"ל נ\"ל והוא שיש בה דגן כזית בכדי א\"פ ויאכלנו עכ\"ל:",1,0],[6,5,"מצה שלשה במי וכו'. כ' הראב\"ד ז\"ל אע\"ג דתניא בתוספ' יוצאין במצה מתובלת בין שתבלה בקדרה בין שתבלה באלפס ההיא שתבלה משנאפת עכ\"ל:",2,0],[6,6,"אחד מצה שנאפית וכו'. כתב הראב\"ד ז\"ל מעשה אילפס אע\"ג דלחם הוי מיהו איכא למיחש ביה משום חמוץ אא\"כ עשה אותו באילפס וכפה עליו את הכסוי ונפקא לן הא ממילתיה דאביי ורבה בחרוכי תרתי שבלי וממחי קידרי ומחצבא דאבישונא זקיפא אסיר דמאי דפליט מהאי רישא בלע מהאי רישא ומחמיץ עכ\"ל:",1,0],[7,3,"וחוטפין מצה וכו'. א\"א פירוש אחר ממהרין לאכול כדי שלא יישנו עכ\"ל:",1,0],[8,6,"ואחר כך כורך כו'. כתב הראב\"ד ז\"ל זהו כהלל מ\"מ זה הסדר לא דייק עכ\"ל:",1,0],[8,8,"בזמן הזה וכו' ומטבל וכו'. כתב הראב\"ד ז\"ל זה הבל עכ\"ל:",1,0],[8,10,"ויש לו לגמור וכו'. כתב הראב\"ד ז\"ל אין הדעת מקבלת כן לפי שאין כאן שם לארבעה כוסות אם אינן במקום אחד עכ\"ל:",1,0],[8,14,"מי שישן וכו'. א\"א אם פסח היה אוכל והוא יחידי אינו חוזר ואוכל ממנו משום היסח הדעת נפסל אם לא היה שם פסח נוטל ידיו ומברך המוציא ואוכל שהשינה מפסיקתו והוא שישנו כלן ואתא ר\"י למימר דאפילו כלן אם נתנמנמו יאכלו דלא הוי היסח הדעת לגבי פסח ולגבי אכילה נמי לא הוי הפסק וקיי\"ל כרבי יוסי דרבה יליף מיניה עכ\"ל:",1,0]]);
